/**
 * Additional bundled knowledge: short, original explainers across many subjects.
 * Compact tuples keep the source small; knowledge.ts converts them to RAG docs.
 */
import type { KnowledgeEntry } from './knowledge';

type FullRow = [title: string, keys: string, topic: string, text: string];
type CompactRow = [title: string, keys: string, gloss: string];

const compact = (topic: string, rows: CompactRow[]): FullRow[] =>
  rows.map(([title, keys, gloss]) => [
    title,
    keys,
    topic,
    /[.!?]$/.test(gloss) ? gloss : `${title} is ${gloss}.`,
  ]);

